import React, { useState, useMemo, useCallback } from 'react';
import { createPortal } from 'react-dom';
import type { BankStatementImportRow, BatchDetailLine } from '../../../../../services/kt/bankStatementImportModels';
import { extractBulkRefsFromDescription, normalizeBulkRef } from '../../../../../utils/extractBatchRefs';
import styles from './Step1Upload.module.css';

function formatAmount(n?: number): string {
  if (n == null) return '—';
  return n.toLocaleString('vi-VN');
}

/** Tiền GD: ưu tiên Nợ (chi) → Có (thu) → amount. */
function gdAmount(row: BankStatementImportRow): number {
  return row.debitAmount || row.creditAmount || row.amount || 0;
}

/**
 * GD lô cần đối soát = thiếu đối tác và thiếu NH đối tác.
 * UNC/CK đơn đã có đủ thông tin đối tác/NH → bỏ qua.
 */
function isBatchHubCandidate(row: BankStatementImportRow): boolean {
  const hasCounterparty = !!(row.counterpartyName && row.counterpartyName.trim());
  const hasPartnerBank = !!(row.partnerBankName && row.partnerBankName.trim());
  return !hasCounterparty && !hasPartnerBank;
}

function PortalOverlay(props: { onClose: () => void; children: React.ReactNode }): React.ReactElement {
  return createPortal(
    <div className={styles.explainOverlay} onClick={props.onClose} role="presentation">
      {props.children}
    </div>,
    document.body,
  );
}

/** Chuẩn hoá ngày DD/MM/YYYY | D/M/YYYY | có giờ | ISO → key so khớp. */
function normDateKey(d?: string): string {
  if (!d) return '';
  const s = d.trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) {
    return `${iso[3].padStart(2, '0')}/${iso[2].padStart(2, '0')}/${iso[1]}`;
  }
  const m = s.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!m) return s;
  const dd = m[1].padStart(2, '0');
  const mm = m[2].padStart(2, '0');
  let yyyy = m[3];
  if (yyyy.length === 2) yyyy = `20${yyyy}`;
  return `${dd}/${mm}/${yyyy}`;
}

interface BatchReconcileProps {
  saoke: BankStatementImportRow[];
  batches: { file: File; lines: BatchDetailLine[] }[];
}

type BRecGroup = {
  batchRef: string;
  sheetDate?: string;
  fileName: string;
  /** Relative path file (không lineno) hoặc path:line từ dòng đầu. */
  sourcePath?: string;
  lineCount: number;
  totalAmount: number;
  lines: BatchDetailLine[];
};

/** Path hiển thị trên grid — ưu tiên sourcePath dòng; fallback tên file. */
function batchGroupPath(g: { sourcePath?: string; fileName?: string; lines?: BatchDetailLine[] }): string {
  const fromLine = g.lines?.find(l => l.sourcePath)?.sourcePath;
  return fromLine || g.sourcePath || g.fileName || '—';
}

/**
 * Đối soát: danh sách GD sao kê có thông tin lô.
 * Click GD → slide-out chọn/đổi/gán nhiều lô (1 GD ↔ nhiều lô).
 * Filter/sort lô theo ngày — default = ngày giao dịch của GD.
 */
const BatchReconcilePanel: React.FC<BatchReconcileProps> = ({ saoke, batches }) => {
  const [manualMap, setManualMap] = useState<Record<string, number>>({});
  const [suppressedAuto, setSuppressedAuto] = useState<Record<string, true>>({});
  /** GD đang mở slide-out gán lô (giữ object — tránh find theo rowIndex trùng). */
  const [assignGd, setAssignGd] = useState<BankStatementImportRow | null>(null);
  /** Lô đang tick trong slide-out. */
  const [selectedBatchRefs, setSelectedBatchRefs] = useState<string[]>([]);
  const [batchSearch, setBatchSearch] = useState('');
  /** Filter ngày lô trong slide-out — default = ngày GD. */
  const [batchDateFilter, setBatchDateFilter] = useState<string>('');
  const [listDateFilter, setListDateFilter] = useState<string>('');
  const [filterMode, setFilterMode] = useState<'all' | 'mapped' | 'mismatched' | 'unmapped'>('all');
  const [detailLine, setDetailLine] = useState<{ batchRef: string; idx: number } | null>(null);

  const bgroups = useMemo((): BRecGroup[] => {
    const map = new Map<string, BRecGroup>();
    for (const d of batches) {
      const rel = (d.file as File & { webkitRelativePath?: string }).webkitRelativePath?.trim();
      const filePath = (rel && rel.includes('/')) ? rel.replace(/\\/g, '/') : d.file.name;
      for (const l of d.lines) {
        if (!l.batchRef) continue;
        const key = l.batchRef;
        if (!map.has(key)) {
          map.set(key, {
            batchRef: key,
            sheetDate: l.sheetDate,
            fileName: d.file.name,
            sourcePath: l.sourcePath || filePath,
            lineCount: 0,
            totalAmount: 0,
            lines: [],
          });
        }
        const g = map.get(key)!;
        g.lineCount += 1;
        g.totalAmount += l.amount;
        g.lines.push(l);
        if (!g.sheetDate && l.sheetDate) g.sheetDate = l.sheetDate;
        if (!g.sourcePath && l.sourcePath) g.sourcePath = l.sourcePath;
      }
    }
    return [...map.values()].sort((a, b) =>
      (a.sheetDate ?? '').localeCompare(b.sheetDate ?? '') || a.batchRef.localeCompare(b.batchRef),
    );
  }, [batches]);

  const bgroupByRef = useMemo(() => {
    const m = new Map<string, BRecGroup>();
    for (const g of bgroups) m.set(g.batchRef, g);
    return m;
  }, [bgroups]);

  const autoMap = useMemo(() => {
    const m = new Map<string, BankStatementImportRow>();
    for (const row of saoke) {
      if ((row.debitAmount ?? 0) <= 0) continue;
      const refs = extractBulkRefsFromDescription(row.description);
      for (const ref of refs) {
        const norm = normalizeBulkRef(ref);
        for (const g of bgroups) {
          if (normalizeBulkRef(g.batchRef) === norm || g.batchRef === ref) {
            if (!m.has(g.batchRef)) m.set(g.batchRef, row);
          }
        }
      }
    }
    return m;
  }, [saoke, bgroups]);

  const resolveMappedRow = useCallback((batchRef: string): BankStatementImportRow | undefined => {
    const manualIdx = manualMap[batchRef];
    if (manualIdx !== undefined) return saoke.find(r => r.rowIndex === manualIdx);
    if (suppressedAuto[batchRef]) return undefined;
    return autoMap.get(batchRef);
  }, [manualMap, suppressedAuto, saoke, autoMap]);

  const batchesForRow = useCallback((rowIndex: number): BRecGroup[] => {
    const refs = new Set<string>();
    for (const [ref, idx] of Object.entries(manualMap)) {
      if (idx === rowIndex) refs.add(ref);
    }
    for (const [ref, row] of autoMap) {
      if (row.rowIndex === rowIndex && manualMap[ref] === undefined && !suppressedAuto[ref]) {
        refs.add(ref);
      }
    }
    return [...refs].map(r => bgroupByRef.get(r)).filter((g): g is BRecGroup => !!g);
  }, [manualMap, autoMap, suppressedAuto, bgroupByRef]);

  const linkedBatchTotal = useCallback((rowIndex: number): number => {
    return batchesForRow(rowIndex).reduce((s, g) => s + g.totalAmount, 0);
  }, [batchesForRow]);

  /** GD lô cần đối soát: chi tiền, thiếu đối tác/NH, có ref lô hoặc đã gắn. */
  const gdRows = useMemo(() => {
    return saoke
      .filter(r => (r.debitAmount ?? 0) > 0)
      .filter(isBatchHubCandidate)
      .filter(r => {
        const refs = extractBulkRefsFromDescription(r.description);
        if (refs.length > 0) return true;
        return batchesForRow(r.rowIndex).length > 0;
      })
      .sort((a, b) => {
        const da = normDateKey(a.transactionDate);
        const db = normDateKey(b.transactionDate);
        return da.localeCompare(db) || (b.debitAmount ?? 0) - (a.debitAmount ?? 0);
      });
  }, [saoke, batchesForRow]);

  const listDateOptions = useMemo(() => {
    const set = new Set<string>();
    for (const r of gdRows) {
      const k = normDateKey(r.transactionDate);
      if (k) set.add(k);
    }
    return [...set].sort();
  }, [gdRows]);

  const filteredGdRows = useMemo(() => {
    let rows = gdRows;
    if (listDateFilter) {
      rows = rows.filter(r => normDateKey(r.transactionDate) === listDateFilter);
    }
    if (filterMode === 'mapped') {
      rows = rows.filter(r => {
        const linked = batchesForRow(r.rowIndex);
        if (linked.length === 0) return false;
        return Math.abs((r.debitAmount ?? 0) - linkedBatchTotal(r.rowIndex)) <= 1;
      });
    } else if (filterMode === 'mismatched') {
      rows = rows.filter(r => {
        const linked = batchesForRow(r.rowIndex);
        if (linked.length === 0) return false;
        return Math.abs((r.debitAmount ?? 0) - linkedBatchTotal(r.rowIndex)) > 1;
      });
    } else if (filterMode === 'unmapped') {
      rows = rows.filter(r => batchesForRow(r.rowIndex).length === 0);
    }
    return rows;
  }, [gdRows, listDateFilter, filterMode, batchesForRow, linkedBatchTotal]);

  const mappedCount = useMemo(
    () => gdRows.filter(r => batchesForRow(r.rowIndex).length > 0
      && Math.abs((r.debitAmount ?? 0) - linkedBatchTotal(r.rowIndex)) <= 1).length,
    [gdRows, batchesForRow, linkedBatchTotal],
  );
  const mismatchedCount = useMemo(
    () => gdRows.filter(r => batchesForRow(r.rowIndex).length > 0
      && Math.abs((r.debitAmount ?? 0) - linkedBatchTotal(r.rowIndex)) > 1).length,
    [gdRows, batchesForRow, linkedBatchTotal],
  );
  const unmappedCount = useMemo(
    () => gdRows.filter(r => batchesForRow(r.rowIndex).length === 0).length,
    [gdRows, batchesForRow],
  );

  const assignGdIdx = assignGd?.rowIndex ?? null;

  const batchDateOptions = useMemo(() => {
    const set = new Set<string>();
    for (const g of bgroups) {
      const k = normDateKey(g.sheetDate);
      if (k) set.add(k);
    }
    // Luôn có option = ngày GD đang mở (kể cả chưa có lô ngày đó)
    if (batchDateFilter) set.add(batchDateFilter);
    return [...set].sort();
  }, [bgroups, batchDateFilter]);

  const pickerBatches = useMemo(() => {
    const q = batchSearch.trim().toLowerCase();
    let list = bgroups;
    if (batchDateFilter) {
      list = list.filter(g => normDateKey(g.sheetDate) === batchDateFilter);
    }
    if (q) {
      list = list.filter(g =>
        g.batchRef.toLowerCase().includes(q)
        || g.fileName.toLowerCase().includes(q)
        || g.lines.some(l => (l.description ?? '').toLowerCase().includes(q)
          || (l.beneficiaryName ?? '').toLowerCase().includes(q)
          || (l.staffNote ?? '').toLowerCase().includes(q)),
      );
    }
    return [...list].sort((a, b) =>
      (a.sheetDate ?? '').localeCompare(b.sheetDate ?? '') || a.batchRef.localeCompare(b.batchRef),
    );
  }, [bgroups, batchDateFilter, batchSearch]);

  const selectedBatches = useMemo(
    () => selectedBatchRefs
      .map(ref => bgroupByRef.get(ref))
      .filter((g): g is BRecGroup => !!g),
    [selectedBatchRefs, bgroupByRef],
  );

  /** Picker chỉ hiện lô chưa chọn — đã chọn nằm section riêng. */
  const availablePickerBatches = useMemo(
    () => pickerBatches.filter(g => !selectedBatchRefs.includes(g.batchRef)),
    [pickerBatches, selectedBatchRefs],
  );

  const selectedSum = useMemo(
    () => selectedBatches.reduce((s, g) => s + g.totalAmount, 0),
    [selectedBatches],
  );
  const gdAmt = assignGd ? gdAmount(assignGd) : 0;
  const assignDiff = gdAmt - selectedSum;
  const assignMatch = selectedBatchRefs.length > 0 && Math.abs(assignDiff) < 1;

  const openAssignForGd = useCallback((row: BankStatementImportRow) => {
    setDetailLine(null);
    setBatchSearch('');
    setAssignGd(prev => {
      if (prev && prev.rowIndex === row.rowIndex
        && prev.description === row.description
        && prev.transactionDate === row.transactionDate) {
        setSelectedBatchRefs([]);
        setBatchDateFilter('');
        return null;
      }
      const gdDate = normDateKey(row.transactionDate);
      setBatchDateFilter(gdDate);
      setSelectedBatchRefs(batchesForRow(row.rowIndex).map(g => g.batchRef));
      return row;
    });
  }, [batchesForRow]);

  const closeAssign = useCallback(() => {
    setAssignGd(null);
    setSelectedBatchRefs([]);
    setDetailLine(null);
    setBatchSearch('');
    setBatchDateFilter('');
  }, []);

  const toggleBatch = useCallback((batchRef: string) => {
    setSelectedBatchRefs(prev =>
      prev.includes(batchRef) ? prev.filter(r => r !== batchRef) : [...prev, batchRef],
    );
  }, []);

  const confirmAssign = useCallback(() => {
    if (assignGdIdx == null) return;
    const prevLinked = new Set(batchesForRow(assignGdIdx).map(g => g.batchRef));
    const next = new Set(selectedBatchRefs);

    setManualMap(prev => {
      const n = { ...prev };
      for (const ref of prevLinked) {
        if (!next.has(ref)) delete n[ref];
      }
      for (const ref of next) n[ref] = assignGdIdx;
      return n;
    });
    setSuppressedAuto(prev => {
      const n = { ...prev };
      for (const ref of next) delete n[ref];
      for (const ref of prevLinked) {
        if (!next.has(ref)) n[ref] = true;
      }
      return n;
    });
    closeAssign();
  }, [assignGdIdx, selectedBatchRefs, batchesForRow, closeAssign]);

  if (batches.length === 0 || saoke.length === 0) {
    return (
      <div className={styles.reconcileEmpty}>
        Cần có cả file <strong>sao kê</strong> và file <strong>thanh toán lô</strong> để đối soát
      </div>
    );
  }

  if (bgroups.length === 0) {
    return (
      <div className={styles.reconcileEmpty}>
        Không phát hiện lệnh CK lô nào (thiếu Ref No trong header file thanh toán lô?)
      </div>
    );
  }

  const detailBatch = detailLine ? bgroupByRef.get(detailLine.batchRef) : undefined;
  const detailLineRow = detailBatch && detailLine ? detailBatch.lines[detailLine.idx] : undefined;

  return (
    <div className={styles.reconcilePanel}>
      <div className={styles.reconcileStats}>
        <button
          className={`${styles.reconcileStat} ${filterMode === 'all' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode('all')}
        >
          <span className={styles.reconcileStatVal}>{gdRows.length}</span> GD lô (thiếu ĐT)
        </button>
        <button
          className={`${styles.reconcileStat} ${styles.reconcileStatOk} ${filterMode === 'mapped' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode(prev => (prev === 'mapped' ? 'all' : 'mapped'))}
        >
          <span className={styles.reconcileStatVal}>{mappedCount}</span> khớp
        </button>
        <button
          className={`${styles.reconcileStat} ${mismatchedCount > 0 ? styles.reconcileStatErr : styles.reconcileStatOk} ${filterMode === 'mismatched' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode(prev => (prev === 'mismatched' ? 'all' : 'mismatched'))}
        >
          <span className={styles.reconcileStatVal}>{mismatchedCount}</span> lệch tiền
        </button>
        <button
          className={`${styles.reconcileStat} ${unmappedCount > 0 ? styles.reconcileStatWarn : styles.reconcileStatOk} ${filterMode === 'unmapped' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode(prev => (prev === 'unmapped' ? 'all' : 'unmapped'))}
        >
          <span className={styles.reconcileStatVal}>{unmappedCount}</span> chưa gắn lô
        </button>

        <label className={styles.reconcileDateFilter}>
          <span>Ngày GD</span>
          <select
            value={listDateFilter}
            onChange={e => setListDateFilter(e.target.value)}
          >
            <option value="">Tất cả ngày</option>
            {listDateOptions.map(d => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </label>
      </div>

      <div className={styles.reconcileTableWrap}>
        <table className={styles.reconcileTable}>
          <thead>
            <tr>
              <th className={styles.reconcileTh}>#</th>
              <th className={styles.reconcileTh}>Ngày</th>
              <th className={styles.reconcileTh}>Nội dung / mã GD sao kê</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThR}`}>Tiền SK</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThC}`}># lô</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThR}`}>Tổng lô</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThR}`}>Chênh</th>
              <th className={styles.reconcileTh}></th>
              <th className={styles.reconcileTh}>Chứng từ gốc</th>
            </tr>
          </thead>
          <tbody>
            {filteredGdRows.length === 0 ? (
              <tr>
                <td colSpan={9} className={styles.reconcileEmpty}>
                  Không có GD lô cần đối soát (đã lọc bỏ GD có đủ đối tác / ngân hàng)
                </td>
              </tr>
            ) : filteredGdRows.map((row, idx) => {
              const linked = batchesForRow(row.rowIndex);
              const batchSum = linkedBatchTotal(row.rowIndex);
              const rowAmt = gdAmount(row);
              const variance = rowAmt - batchSum;
              const isMismatch = linked.length > 0 && Math.abs(variance) > 1;
              const isOpen = assignGd != null
                && assignGd.rowIndex === row.rowIndex
                && assignGd.description === row.description
                && assignGd.transactionDate === row.transactionDate;
              const refsInDesc = extractBulkRefsFromDescription(row.description);
              const rowCls = [
                styles.reconcileTr,
                linked.length === 0 ? styles.reconcileTrMissing
                  : isMismatch ? styles.reconcileTrMismatch : styles.reconcileTrOk,
                isOpen ? styles.reconcileTrExplain : '',
              ].join(' ');

              return (
                <tr
                  key={`gd-${row.rowIndex}-${row.referenceCode ?? ''}-${row.transactionDate ?? ''}`}
                  className={rowCls}
                  style={{ cursor: 'pointer' }}
                  onClick={() => openAssignForGd(row)}
                >
                  <td className={styles.reconcileTd}>{idx + 1}</td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileTdDate}`}>
                    {row.transactionDate ?? '—'}
                  </td>
                  <td className={styles.reconcileTd}>
                    <div className={styles.reconcileRowDesc}>{row.description ?? '—'}</div>
                    <div className={styles.reconcileRowMeta}>
                      {refsInDesc.length > 0 && (
                        <span className={styles.reconcileMultiHint}>
                          Ref: {refsInDesc.slice(0, 3).join(', ')}
                          {refsInDesc.length > 3 ? '…' : ''}
                        </span>
                      )}
                      {linked.length > 0 && (
                        <span>
                          {' · '}
                          {linked.map(g => g.batchRef).slice(0, 2).join(', ')}
                          {linked.length > 2 ? ` +${linked.length - 2}` : ''}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileThR}`} style={{ fontWeight: 700 }}>
                    {formatAmount(rowAmt)}
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileThC}`}>{linked.length || '—'}</td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileTdAmtBatch}`}>
                    {linked.length ? formatAmount(batchSum) : '—'}
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileThR}`}>
                    {linked.length === 0 ? '—' : (
                      <span style={{ fontWeight: 700, color: Math.abs(variance) < 1 ? '#15803d' : '#dc2626' }}>
                        {Math.abs(variance) < 1 ? '✓ Khớp' : `${variance > 0 ? '+' : ''}${formatAmount(variance)}`}
                      </span>
                    )}
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileActions}`} onClick={e => e.stopPropagation()}>
                    <button className={styles.reconcileLookupBtn} onClick={() => openAssignForGd(row)}>
                      {isOpen ? '✕ Đóng' : linked.length ? 'Đổi lô' : '+ Gán lô'}
                    </button>
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.categoryTdPath}`} title={row.importReference || undefined}>
                    <div className={styles.pathCell}>{row.importReference || '—'}</div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Slide-out: gán nhiều lô cho 1 GD */}
      {assignGd && (
        <PortalOverlay onClose={closeAssign}>
          <aside
            className={`${styles.explainSlideout} ${styles.assignSlideout}`}
            onClick={e => e.stopPropagation()}
            role="dialog"
            aria-label="Gán lô cho giao dịch sao kê"
          >
            <div className={styles.explainCardHeader}>
              <div className={styles.explainCardTitle}>
                <span className={styles.explainCardBadge}>Gán lô → GD</span>
                <span className={styles.explainCardDate}>{assignGd.transactionDate ?? '—'}</span>
                <span className={styles.explainCardAmt}>{formatAmount(gdAmt)}</span>
              </div>
              <button type="button" className={styles.explainCardClose} onClick={closeAssign}>✕</button>
            </div>

            <div className={styles.assignSumBar} data-match={selectedBatchRefs.length ? (assignMatch ? '1' : '0') : ''}>
              <div className={styles.assignSumItem}>
                <span>Tiền GD sao kê</span>
                <b>{formatAmount(gdAmt)}</b>
              </div>
              <div className={styles.assignSumItem}>
                <span>Tổng {selectedBatchRefs.length} lô chọn</span>
                <b>{selectedBatchRefs.length ? formatAmount(selectedSum) : '—'}</b>
              </div>
              <div className={styles.assignSumItem}>
                <span>Khớp?</span>
                <b style={{ color: !selectedBatchRefs.length ? '#9ca3af' : assignMatch ? '#15803d' : '#dc2626' }}>
                  {!selectedBatchRefs.length
                    ? '—'
                    : assignMatch
                      ? '✓ Khớp'
                      : `Lệch ${assignDiff > 0 ? '+' : ''}${formatAmount(assignDiff)}`}
                </b>
              </div>
              {selectedBatchRefs.length > 0 && !assignMatch && (
                <div className={styles.assignWarn}>
                  ⚠ Tổng lô chưa khớp tiền GD — 1 GD có thể gắn nhiều lô; vẫn lưu được.
                </div>
              )}
            </div>

            <div className={styles.explainSlideBody}>
              {/* Full thông tin GD sao kê */}
              <div className={styles.assignGdInfo}>
                <div className={styles.batchMdTitle}>Thông tin giao dịch sao kê</div>
                <div className={styles.lineDetailBody}>
                  <div className={styles.batchLineDetailGrid}>
                    <div>
                      <span>Ngày GD</span>
                      <b>{assignGd.transactionDate ?? '—'}</b>
                    </div>
                    <div>
                      <span>Số tiền</span>
                      <b style={{ color: (assignGd.debitAmount ?? 0) > 0 ? '#b91c1c' : '#15803d' }}>
                        {formatAmount(gdAmt)}
                        {(assignGd.debitAmount ?? 0) > 0 ? ' (Chi)' : (assignGd.creditAmount ?? 0) > 0 ? ' (Thu)' : ''}
                      </b>
                    </div>
                    <div>
                      <span>Phát sinh Nợ</span>
                      <b>{formatAmount(assignGd.debitAmount)}</b>
                    </div>
                    <div>
                      <span>Phát sinh Có</span>
                      <b>{formatAmount(assignGd.creditAmount)}</b>
                    </div>
                    <div>
                      <span>Đối tác</span>
                      <b>{assignGd.counterpartyName || '—'}</b>
                    </div>
                    <div>
                      <span>Ngân hàng ĐT</span>
                      <b>{assignGd.partnerBankName || '—'}</b>
                    </div>
                    <div>
                      <span>Số TK / mã NH</span>
                      <b style={{ fontFamily: 'monospace' }}>{assignGd.bankAccountCode || '—'}</b>
                    </div>
                    <div>
                      <span>Mã tham chiếu</span>
                      <b style={{ fontFamily: 'monospace' }}>{assignGd.referenceCode || '—'}</b>
                    </div>
                    <div>
                      <span>Chứng từ gốc</span>
                      <b className={styles.pathCell} title={assignGd.importReference || undefined}>
                        {assignGd.importReference || '—'}
                      </b>
                    </div>
                    <div>
                      <span>Nghiệp vụ</span>
                      <b>{assignGd.postingCategoryLabel || assignGd.postingCategoryCode || '—'}</b>
                    </div>
                    <div>
                      <span>Ref lô (từ nội dung)</span>
                      <b style={{ fontFamily: 'monospace', wordBreak: 'break-all' }}>
                        {(() => {
                          const refs = [
                            ...(assignGd.detectedBatchRefs ?? []),
                            ...extractBulkRefsFromDescription(assignGd.description),
                          ];
                          const uniq = [...new Set(refs.map(normalizeBulkRef).filter(Boolean))];
                          return uniq.length ? uniq.join(', ') : '—';
                        })()}
                      </b>
                    </div>
                    {(assignGd.noteCustomerCode || assignGd.noteCustomerName) && (
                      <div>
                        <span>Ghi chú khách hàng</span>
                        <b style={{ color: '#4338ca' }}>
                          {[assignGd.noteCustomerCode, assignGd.noteCustomerName].filter(Boolean).join(' — ')}
                        </b>
                      </div>
                    )}
                    {assignGd.expenseNote && (
                      <div>
                        <span>Nội dung (ghi chú)</span>
                        <b style={{ color: '#9a3412' }}>{assignGd.expenseNote}</b>
                      </div>
                    )}
                    <div className={styles.batchLineDetailFull}>
                      <span>Nội dung CK</span>
                      <b className={styles.descFull}>{assignGd.description || '—'}</b>
                    </div>
                  </div>
                </div>
              </div>

              {/* 1 — Lô đã chọn */}
              <div className={styles.assignSelectedSection}>
                <div className={styles.batchMdTitle}>
                  1. Lô đã chọn
                  <span className={styles.batchMdTitleMeta}>
                    {selectedBatches.length} lô · {formatAmount(selectedSum)}
                  </span>
                </div>
                {selectedBatches.length === 0 ? (
                  <div className={styles.assignSelectedEmpty}>
                    Chưa chọn lô — chọn ở mục «2. Chọn lô để gắn» bên dưới
                  </div>
                ) : (
                  <div className={styles.assignSelectedList}>
                    {selectedBatches.map(g => {
                      const notes = [...new Set(g.lines.map(l => l.staffNote || l.companyCode).filter(Boolean))];
                      const path = batchGroupPath(g);
                      return (
                        <div key={g.batchRef} className={styles.assignSelectedItem}>
                          <div className={styles.assignSelectedMain}>
                            <span className={styles.reconcileBatchRef}>{g.batchRef}</span>
                            <span className={styles.assignSelectedDate}>{g.sheetDate ?? '—'}</span>
                            <span className={styles.assignSelectedAmt}>{formatAmount(g.totalAmount)}</span>
                            <span className={styles.assignSelectedMeta}>
                              {g.lineCount} dòng
                              {notes.length > 0 ? ` · ${notes.slice(0, 2).join(', ')}` : ''}
                            </span>
                            <span className={styles.pathCell} title={path}>{path}</span>
                          </div>
                          <div className={styles.assignSelectedActions}>
                            <button
                              type="button"
                              className={styles.reconcileLookupBtn}
                              onClick={() => setDetailLine({ batchRef: g.batchRef, idx: 0 })}
                            >
                              Chi tiết
                            </button>
                            <button
                              type="button"
                              className={styles.assignRemoveBtn}
                              onClick={() => toggleBatch(g.batchRef)}
                              title="Bỏ chọn lô"
                            >
                              Bỏ
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* 2 — Chọn lô để gắn */}
              <div className={styles.assignPickerSection}>
                <div className={styles.batchMdTitle}>
                  2. Chọn lô để gắn
                  <span className={styles.batchMdTitleMeta}>tick để thêm vào mục 1 · filter mặc định = ngày GD</span>
                </div>
                <div className={styles.assignPickerInner}>
                  <div className={styles.reconcileDateFilterRow}>
                    <label className={styles.reconcileDateFilter}>
                      <span>Ngày lô</span>
                      <select
                        value={batchDateFilter}
                        onChange={e => setBatchDateFilter(e.target.value)}
                      >
                        <option value="">Tất cả ngày</option>
                        {batchDateOptions.map(d => (
                          <option key={d} value={d}>{d}</option>
                        ))}
                      </select>
                    </label>
                    {batchDateFilter && availablePickerBatches.length === 0 && pickerBatches.length === 0 && (
                      <span className={styles.reconcileMultiHint}>
                        Không có lô ngày {batchDateFilter} — chọn «Tất cả ngày» hoặc ngày khác
                      </span>
                    )}
                    <input
                      className={styles.reconcileLookupInput}
                      style={{ flex: 1, marginBottom: 0 }}
                      placeholder="Tìm mã lô, nội dung, ghi chú NV…"
                      value={batchSearch}
                      onChange={e => setBatchSearch(e.target.value)}
                    />
                  </div>

                  <div className={styles.assignTableWrap}>
                    <table className={`${styles.categoryTable} ${styles.assignNoSticky}`}>
                      <thead>
                        <tr>
                          <th className={styles.categoryTh} style={{ width: 36 }} />
                          <th className={styles.categoryTh} style={{ minWidth: 140 }}>Mã lô (Ref)</th>
                          <th className={styles.categoryTh} style={{ width: 88 }}>Ngày</th>
                          <th className={styles.categoryTh} style={{ width: 110, textAlign: 'right' }}>Tổng tiền</th>
                          <th className={styles.categoryTh} style={{ width: 56, textAlign: 'center' }}>#</th>
                          <th className={styles.categoryTh}>File / ghi chú NV</th>
                          <th className={styles.categoryTh} style={{ minWidth: 140 }}>Chứng từ gốc</th>
                        </tr>
                      </thead>
                      <tbody>
                        {availablePickerBatches.length === 0 ? (
                          <tr>
                            <td colSpan={7} className={styles.reconcileEmpty}>
                              {pickerBatches.length > 0 && selectedBatches.length > 0
                                ? 'Đã chọn hết lô trong filter hiện tại'
                                : 'Không có lô (đổi filter ngày / tìm kiếm)'}
                            </td>
                          </tr>
                        ) : availablePickerBatches.map(g => {
                          const notes = [...new Set(g.lines.map(l => l.staffNote || l.companyCode).filter(Boolean))];
                          const path = batchGroupPath(g);
                          return (
                            <tr
                              key={g.batchRef}
                              className={styles.categoryTr}
                              onClick={() => toggleBatch(g.batchRef)}
                            >
                              <td className={styles.categoryTd} style={{ textAlign: 'center' }}>
                                <input
                                  type="checkbox"
                                  checked={false}
                                  onChange={() => toggleBatch(g.batchRef)}
                                  onClick={e => e.stopPropagation()}
                                />
                              </td>
                              <td className={styles.categoryTd}>
                                <span className={styles.reconcileBatchRef}>{g.batchRef}</span>
                              </td>
                              <td className={styles.categoryTd} style={{ color: '#2563eb', fontWeight: 600, whiteSpace: 'nowrap' }}>
                                {g.sheetDate ?? '—'}
                              </td>
                              <td className={styles.categoryTd} style={{ textAlign: 'right', fontWeight: 700, color: '#7c3aed' }}>
                                {formatAmount(g.totalAmount)}
                              </td>
                              <td className={styles.categoryTd} style={{ textAlign: 'center' }}>{g.lineCount}</td>
                              <td className={styles.categoryTd}>
                                <div className={styles.descSub}>{g.fileName.replace(/\.[^.]+$/, '')}</div>
                                {notes.length > 0 && (
                                  <div style={{ color: '#9a3412', fontWeight: 600, fontSize: 11 }}>
                                    {notes.slice(0, 4).join(', ')}{notes.length > 4 ? '…' : ''}
                                  </div>
                                )}
                                <button
                                  type="button"
                                  className={styles.reconcileLookupBtn}
                                  style={{ marginTop: 4 }}
                                  onClick={e => {
                                    e.stopPropagation();
                                    setDetailLine({ batchRef: g.batchRef, idx: 0 });
                                  }}
                                >
                                  Xem chi tiết
                                </button>
                              </td>
                              <td className={`${styles.categoryTd} ${styles.categoryTdPath}`} title={path}>
                                <div className={styles.pathCell}>{path}</div>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>

            <div className={styles.assignFooter}>
              <button type="button" className={styles.assignCancelBtn} onClick={closeAssign}>Hủy</button>
              <button type="button" className={styles.assignConfirmBtn} onClick={confirmAssign}>
                Lưu gắn lô ({selectedBatchRefs.length})
              </button>
            </div>
          </aside>

          {detailBatch && detailLineRow && (
            <aside
              className={`${styles.explainSlideout} ${styles.lineDetailSlideout}`}
              onClick={e => e.stopPropagation()}
              role="dialog"
              aria-label="Chi tiết lô"
              style={{ boxShadow: '-12px 0 28px rgba(15,23,42,0.25)' }}
            >
              <div className={styles.explainCardHeader}>
                <div className={styles.explainCardTitle}>
                  <span className={styles.explainCardBadge}>Chi tiết lô</span>
                  <span className={styles.reconcileBatchRef}>{detailBatch.batchRef}</span>
                  <span className={styles.explainCardAmt}>{formatAmount(detailBatch.totalAmount)}</span>
                </div>
                <button type="button" className={styles.explainCardClose} onClick={() => setDetailLine(null)}>✕</button>
              </div>
              <div className={styles.explainSlideBody}>
                <div className={styles.assignDetailScroll} style={{ maxHeight: 'none', flex: 1 }}>
                  <table className={`${styles.categoryTable} ${styles.assignNoSticky}`}>
                    <thead>
                      <tr>
                        <th className={styles.categoryTh}>#</th>
                        <th className={styles.categoryTh}>Người nhận</th>
                        <th className={styles.categoryTh} style={{ textAlign: 'right' }}>Tiền</th>
                        <th className={styles.categoryTh}>Nội dung</th>
                        <th className={styles.categoryTh}>Ghi chú NV</th>
                        <th className={styles.categoryTh} style={{ minWidth: 140 }}>Chứng từ gốc</th>
                      </tr>
                    </thead>
                    <tbody>
                      {detailBatch.lines.map((l, i) => (
                        <tr key={`${detailBatch.batchRef}-${i}`} className={styles.categoryTr}>
                          <td className={styles.categoryTd}>{i + 1}</td>
                          <td className={styles.categoryTd}>
                            <div className={styles.descFull}>{l.beneficiaryName}</div>
                            <div className={styles.descSub}>{l.bankName}</div>
                          </td>
                          <td className={styles.categoryTd} style={{ textAlign: 'right', color: '#7c3aed', fontWeight: 700 }}>
                            {formatAmount(l.amount)}
                          </td>
                          <td className={`${styles.categoryTd} ${styles.categoryTdDesc}`}>
                            <div className={styles.descFull}>{l.description || '—'}</div>
                          </td>
                          <td className={styles.categoryTd} style={{ color: '#9a3412', fontWeight: 600 }}>
                            {l.staffNote || l.companyCode || '—'}
                          </td>
                          <td className={`${styles.categoryTd} ${styles.categoryTdPath}`} title={l.sourcePath || undefined}>
                            <div className={styles.pathCell}>{l.sourcePath || '—'}</div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </aside>
          )}
        </PortalOverlay>
      )}
    </div>
  );
};

export default BatchReconcilePanel;
